import React from "react";

const gradeColor = (score) => {
  if (score >= 90) return "#43e97b";
  if (score >= 75) return "#6c63ff";
  if (score >= 60) return "#f7971e";
  return "#ff6584";
};

const gradeClass = (avg) => {
  if (avg >= 90) return "grade-a";
  if (avg >= 75) return "grade-b";
  if (avg >= 60) return "grade-c";
  return "grade-d";
};

const gradeLabel = (avg) => {
  if (avg >= 90) return "A";
  if (avg >= 75) return "B";
  if (avg >= 60) return "C";
  return "D";
};

export default function StudentDetail({ student, onClose, onEdit }) {
  if (!student) return null;
  const grades = student.grades || {};
  const subjects = Object.keys(grades);
  const avg = student.average || 0;

  return (
    <div className="modal-overlay" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal fade-in" style={{ maxWidth: 520 }}>
        <div className="modal-header">
          <div className="modal-title">🎓 Student Profile</div>
          <button className="modal-close" onClick={onClose}>✕</button>
        </div>
        <div className="modal-body">
          {/* Header */}
          <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 24, padding: 16, background: "var(--surface2)", borderRadius: "var(--radius-sm)" }}>
            <div style={{
              width: 56, height: 56, borderRadius: "50%",
              background: "linear-gradient(135deg, var(--accent), var(--accent2))",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: "1.5rem", fontWeight: 800, color: "#fff", fontFamily: "var(--font-display)",
              flexShrink: 0,
            }}>
              {student.name?.charAt(0)?.toUpperCase()}
            </div>
            <div style={{ flex: 1 }}>
              <div style={{ fontFamily: "var(--font-display)", fontWeight: 800, fontSize: "1.1rem" }}>{student.name}</div>
              <div style={{ color: "var(--text3)", fontSize: "0.82rem" }}>{student.email}</div>
              <div style={{ marginTop: 6, display: "flex", gap: 6, flexWrap: "wrap" }}>
                <span className={`badge badge-${student.status?.toLowerCase()}`}>{student.status}</span>
                <span className="badge" style={{ background: "rgba(108,99,255,0.12)", color: "var(--accent)" }}>{student.course}</span>
                <span className="badge" style={{ background: "var(--surface3)", color: "var(--text2)" }}>Year {student.year}</span>
              </div>
            </div>
            <div style={{ textAlign: "center", flexShrink: 0 }}>
              <div className={`grade-pill ${gradeClass(avg)}`} style={{ fontSize: "1.4rem", padding: "6px 14px" }}>{gradeLabel(avg)}</div>
              <div style={{ fontSize: "0.72rem", color: "var(--text3)", marginTop: 4 }}>{avg}% avg</div>
            </div>
          </div>

          {/* Details */}
          <div className="detail-section">
            <h4>Personal Info</h4>
            <div className="detail-row"><span className="detail-key">Phone</span><span className="detail-val">{student.phone || "—"}</span></div>
            <div className="detail-row"><span className="detail-key">Gender</span><span className="detail-val">{student.gender}</span></div>
            <div className="detail-row"><span className="detail-key">Enrolled</span><span className="detail-val">{new Date(student.enrolledAt).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })}</span></div>
          </div>

          {/* Grades */}
          {subjects.length > 0 && (
            <div className="detail-section">
              <h4>Grades</h4>
              <div className="grades-bar-list">
                {subjects.map((sub) => (
                  <div className="grade-bar-item" key={sub}>
                    <div className="grade-bar-label">
                      <span style={{ color: "var(--text2)", fontSize: "0.82rem" }}>{sub}</span>
                      <span style={{ fontWeight: 700, color: gradeColor(grades[sub]) }}>{grades[sub]}/100</span>
                    </div>
                    <div className="grade-bar-track">
                      <div className="grade-bar-fill" style={{ width: `${grades[sub]}%`, background: gradeColor(grades[sub]) }} />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
        <div className="modal-footer">
          <button className="btn btn-ghost" onClick={onClose}>Close</button>
          <button className="btn btn-primary" onClick={() => { onClose(); onEdit(student); }}>Edit Student</button>
        </div>
      </div>
    </div>
  );
}
